//! Actual trusted insertion decodes exact RCDATA source and nearby App state.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.attr(n,"id")==Some(id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn range_fragment_rcdata_actual_app_trusted_exact_rcdata_insert_keeps_paint_editor_and_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-range-rcdata-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><html><head><style>body{margin:0;background:white}#paint{position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}#paint.ready{background:#228844}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#mount{position:absolute;left:20px;top:180px;width:560px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}</style></head><body><div id=paint>Indicator</div><textarea id=context style="position:absolute;left:20px;top:230px;width:160px;height:40px">Held</textarea><div id=mount></div><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Insert literal source</button><div id=destination></div><script>
var mount=document.getElementById('mount'),context=document.getElementById('context'),watch=new MutationObserver(function(){});watch.observe(mount,{childList:true});document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'actual trusted pointer';var r=document.createRange();r.selectNodeContents(context);var fragment=r.createContextualFragment('\udfff\ud800\r\n&#13;&amp;&NotEqualTilde;&Afr;&#xD800;\0&lt;img id=fake src=missing&gt;&amp;lt;'),text=fragment.firstChild,expected='\udfff\ud800\n\r&\u2242\u0338\ud835\udd04\ufffd\ufffd<img id=fake src=missing>&lt;';if(text.data!==expected||text.data.charCodeAt(0)!==57343||text.data.charCodeAt(1)!==55296||text.ownerDocument!==document||text.parentNode!==fragment||text.isConnected||watch.takeRecords().length||context.value!=='Held'||context.textContent!=='Held')throw 'native exact literal source';mount.appendChild(fragment);var records=watch.takeRecords();if(fragment.firstChild!==null||mount.firstChild!==text||text.data!==expected||!text.isConnected||document.getElementById('fake')!==null||records.length!==1||records[0].target!==mount||records[0].addedNodes[0]!==text||r.startContainer!==context||document.getElementById('neighbor').value!=='edited neighbor')throw 'actual literal Text insertion';document.getElementById('paint').className='ready';document.title='Exact Range RCDATA connected';};
</script></body></html>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);
 let before=app.draw();assert_eq!(before.pixels[(app.content_top()+40)as usize*before.width+110],0x114455);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;
 let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);
 assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,"Exact Range RCDATA connected");
 let mount=node(&app,"mount");let [text]=app.document.nodes[mount].children.as_slice()else{panic!("one actual native Text")};let crate::html::NodeKind::Text(text)=&app.document.nodes[*text].kind else{panic!("native Text")};let units=text.raw_units().unwrap();assert_eq!(&units[..4],&[0xdfff,0xd800,10,13]);assert!(text.as_str().contains("<img id=fake src=missing>&lt;"));assert!(!app.document.nodes.iter().enumerate().any(|(n,_)|app.document.attr(n,"id")==Some("fake")));
 let context=node(&app,"context");assert_eq!(app.forms.controls[&context].value.text(),"Held");let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],0x228844);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);
}
